insert into public.football_derbies (slug, name, english, league, team_a, team_b, sort, intro) values
('north-london-derby', '북런던 더비', 'North London Derby', 'PL', 57, 73, 10, $d$<p>아스널과 토트넘 홋스퍼가 치르는 북런던 더비는 잉글랜드에서 가장 뜨거운 라이벌전 가운데 하나입니다. 아스널이 1913년 런던 남동부 울리치에서 토트넘의 연고지와 가까운 북런던 하이버리로 옮겨 오면서 두 팀은 같은 동네를 다투는 사이가 됐습니다. 1919년 1부 리그 재편 때 아스널이 토트넘을 밀어내고 1부에 들어간 일은 지금까지도 두 팀 팬들 사이에 앙금으로 남아 있습니다.</p><p>아스널 팬들은 시즌 막판 토트넘이 더 이상 아스널을 따라잡을 수 없게 된 날을 "세인트 토터링엄의 날"이라 부르며 기념할 만큼 서로를 의식합니다. 2015년부터 10년 동안은 손흥민이 토트넘의 공격을 이끌며 한국 팬들에게도 특별한 경기가 됐습니다.</p><p>토리코리 관전 포인트: 북런던 더비는 순위와 상관없이 치열하게 흘러 이변이 잦습니다. 두 팀의 이번 시즌 경기당 승점 차이보다 최근 5경기 흐름과 홈 경기 여부를 먼저 보는 것을 권합니다.</p>$d$),
('manchester-derby', '맨체스터 더비', 'Manchester Derby', 'PL', 65, 66, 20, $d$<p>맨체스터 시티와 맨체스터 유나이티드가 한 도시의 주인을 가리는 경기입니다. 두 팀의 전신인 세인트 마크스와 뉴턴 히스가 1881년 처음 맞붙은 이후 140년 넘게 이어진 라이벌전입니다. 오랫동안 유나이티드가 우위를 지켰고, 알렉스 퍼거슨 감독은 시티를 "시끄러운 이웃"이라고 부르기도 했습니다.</p><p>판도는 2008년 시티가 아부다비 자본에 인수되며 바뀌었습니다. 2011년 올드 트래퍼드에서 시티가 6-1로 대승을 거뒀고, 2012년에는 시즌 마지막 날 아구에로의 극장골로 유나이티드를 골득실로 제치고 우승했습니다. 이후 펩 과르디올라 감독 시대에는 시티가 리그를 지배하는 흐름이 이어졌습니다.</p><p>토리코리 관전 포인트: 최근 맞대결은 점유율에서 앞서는 시티와 역습을 노리는 유나이티드의 구도가 많았습니다. 유나이티드가 선제골을 넣는 경기에서 이변이 자주 나왔으니, 전반 흐름을 눈여겨보세요.</p>$d$),
('merseyside-derby', '머지사이드 더비', 'Merseyside Derby', 'PL', 64, 62, 30, $d$<p>리버풀과 에버턴이 같은 도시 리버풀에서 치르는 라이벌전입니다. 원래 안필드는 에버턴의 홈구장이었는데, 1892년 에버턴이 구장 주인과의 갈등 끝에 구디슨 파크로 떠나자 남은 사람들이 새로 만든 구단이 리버풀입니다. 두 경기장이 스탠리 파크를 사이에 두고 마주 보고 있었을 만큼 가까웠습니다.</p><p>한 가족 안에서도 응원 팀이 갈리는 경우가 많아 "친근한 더비"라고 불리지만, 경기장 안에서는 프리미어리그에서 퇴장이 가장 많이 나온 라이벌전으로 꼽힐 만큼 거칠게 치러집니다. 에버턴이 2025-26 시즌 새 경기장으로 옮기면서 구디슨 파크의 더비는 역사 속으로 사라졌습니다.</p><p>토리코리 관전 포인트: 전력 차이가 크더라도 몸싸움과 경고가 많은 경기가 되기 쉽습니다. 이변을 노리는 에버턴은 대체로 수비 블록을 낮추므로, 리버풀이 언제 첫 골을 넣느냐가 경기의 흐름을 좌우합니다.</p>$d$),
('north-west-derby', '노스웨스트 더비', 'North West Derby', 'PL', 64, 66, 40, $d$<p>리버풀과 맨체스터 유나이티드의 경기는 잉글랜드에서 가장 성공한 두 구단의 맞대결입니다. 두 팀 모두 잉글랜드 1부 리그를 20번씩 우승했습니다. 같은 북서부의 두 도시는 19세기 말 맨체스터가 운하를 뚫어 리버풀 항구를 거치지 않고 바다로 나가면서 경제적으로도 경쟁 관계였고, 그 감정이 축구로 이어졌다는 이야기가 전해집니다.</p><p>1990년대 이후에는 퍼거슨 감독의 유나이티드가 우승을 휩쓸었고, 2010년대 후반부터는 리버풀이 다시 정상에 오르며 주도권이 오갔습니다. 순위와 관계없이 두 팀 팬들에게는 시즌에서 가장 중요한 경기로 꼽힙니다.</p><p>토리코리 관전 포인트: 두 팀의 시즌 상황이 크게 달라도 결과를 예측하기 어려운 경기입니다. 맞대결 기록과 함께 두 팀의 최근 실점 흐름을 비교해 보세요.</p>$d$),
('el-clasico', '엘 클라시코', 'El Clásico', 'PD', 81, 86, 50, $d$<p>FC 바르셀로나와 레알 마드리드의 경기는 세계에서 가장 많은 사람이 보는 클럽 경기로 꼽힙니다. 1902년 첫 맞대결 이후 두 팀은 스페인 축구의 양대 산맥으로 경쟁해 왔고, 카탈루냐와 마드리드라는 지역 정체성의 대립까지 겹쳐 단순한 축구 경기 이상의 의미를 갖습니다.</p><p>2000년 루이스 피구가 바르셀로나에서 레알 마드리드로 직행하면서 감정의 골은 더욱 깊어졌고, 2009년부터 약 10년 동안은 메시와 호날두가 매 시즌 엘 클라시코에서 맞붙으며 전 세계의 관심을 모았습니다.</p><p>토리코리 관전 포인트: 두 팀 모두 공격력이 강해 골이 많이 나는 경기가 잦습니다. 이번 시즌 두 팀의 2.5골 오버 비율과 경기당 득점을 함께 보면 경기 양상을 가늠하는 데 도움이 됩니다.</p>$d$),
('madrid-derby', '마드리드 더비', 'Madrid Derby', 'PD', 86, 78, 60, $d$<p>레알 마드리드와 아틀레티코 마드리드가 스페인의 수도를 나눠 쓰는 라이벌전입니다. 오랫동안 레알 마드리드가 우위를 지켰지만, 디에고 시메오네 감독이 아틀레티코를 맡은 뒤로 팽팽한 경쟁 관계가 됐습니다.</p><p>두 팀은 2014년과 2016년 두 번이나 챔피언스리그 결승에서 만났습니다. 2014년 리스본 결승에서는 아틀레티코가 앞서던 경기를 레알 마드리드가 추가시간 세르히오 라모스의 동점골로 연장전까지 끌고 가 뒤집었고, 2016년 밀라노 결승은 승부차기 끝에 레알 마드리드가 이겼습니다.</p><p>토리코리 관전 포인트: 아틀레티코는 수비 블록을 단단히 세우고 역습으로 승부하는 경기가 많아 마드리드 더비는 골이 적게 나는 경우가 많습니다. 선제골의 중요성이 유난히 큰 경기입니다.</p>$d$),
('der-klassiker', '데어 클라시커', 'Der Klassiker', 'BL1', 5, 4, 70, $d$<p>바이에른 뮌헨과 보루시아 도르트문트의 경기는 2000년대 이후 분데스리가를 대표하는 빅매치로 자리 잡으며 "데어 클라시커"라는 이름을 얻었습니다. 독일 남부와 서부를 대표하는 두 구단은 우승을 두고 여러 차례 정면으로 부딪쳤습니다.</p><p>두 팀은 2013년 챔피언스리그 결승에서 맞붙었고, 런던 웸블리에서 바이에른이 후반 막판 아르연 로번의 결승골로 2-1로 이겼습니다. 도르트문트가 키운 스타 선수들이 바이에른으로 옮겨 가는 일이 반복되면서 도르트문트 팬들의 감정은 더욱 날카로워졌습니다.</p><p>토리코리 관전 포인트: 두 팀 모두 공격적인 축구를 해 골이 많은 경기가 자주 나옵니다. 지그날 이두나 파크에서 열리는 경기는 "노란 벽"의 응원 덕분에 홈 이점이 특히 큽니다.</p>$d$),
('revierderby', '레비어 더비', 'Revierderby', 'BL1', 4, 6, 80, $d$<p>보루시아 도르트문트와 샬케 04가 독일 서부 루르 지방에서 치르는 라이벌전입니다. 두 도시는 30km 남짓 떨어진 탄광 도시로, 광산 노동자들의 자존심 대결에서 시작된 이 더비는 독일에서 가장 격렬한 경기로 꼽힙니다.</p><p>샬케가 2020년대 들어 두 차례 2부 리그로 강등되면서 레비어 더비는 몇 시즌 동안 열리지 못했습니다. 그래서 두 팀이 같은 리그에서 다시 만나는 시즌은 지역 전체가 손꼽아 기다리는 축제가 됩니다.</p><p>토리코리 관전 포인트: 레비어 더비는 순위표의 차이가 그대로 결과로 이어지지 않는 경기입니다. 두 팀의 홈·원정 성적과 최근 5경기 흐름을 함께 보세요.</p>$d$),
('milan-derby', '밀라노 더비', 'Derby della Madonnina', 'SA', 98, 108, 90, $d$<p>AC 밀란과 인테르가 같은 경기장 산 시로(주세페 메아차)를 홈으로 쓰며 치르는 라이벌전입니다. 밀라노 대성당 꼭대기의 성모상 "마돈니나"의 이름을 따서 "데르비 델라 마돈니나"라고도 부릅니다. 인테르는 1908년 외국인 선수 영입을 둘러싼 갈등 끝에 밀란에서 갈라져 나온 사람들이 만든 구단이라, 두 팀의 역사는 처음부터 얽혀 있습니다.</p><p>두 팀은 챔피언스리그에서도 여러 번 맞붙었습니다. 2003년 4강은 원정 다득점으로 밀란이 올라갔고, 2005년 8강은 관중석에서 날아든 홍염 때문에 경기가 중단되기도 했습니다. 2023년 4강에서는 인테르가 이겨 결승에 올랐습니다.</p><p>토리코리 관전 포인트: 같은 경기장을 쓰기 때문에 홈 이점이 다른 더비보다 작습니다. 두 팀의 이번 시즌 원정 성적이 결과를 가늠하는 데 오히려 유용합니다.</p>$d$),
('derby-d-italia', '이탈리아 더비', 'Derby d''Italia', 'SA', 108, 109, 100, $d$<p>인테르와 유벤투스의 경기는 1967년 이탈리아의 저명한 축구 기자 잔니 브레라가 붙인 "데르비 디탈리아(이탈리아 더비)"라는 이름으로 불립니다. 같은 도시 팀은 아니지만, 세리에 A에서 가장 많이 우승한 구단들이 맞붙는 경기라 전국적인 관심을 받습니다.</p><p>2006년 승부조작 스캔들(칼치오폴리)로 유벤투스가 강등되고 그 시즌 우승이 인테르에게 돌아가면서 두 팀 팬들 사이의 감정은 더욱 날카로워졌습니다. 이후 두 팀은 리그 우승을 두고 번갈아 정상을 차지하며 경쟁을 이어 왔습니다.</p><p>토리코리 관전 포인트: 두 팀 모두 수비 조직이 탄탄한 편이라 한두 골 차로 승부가 갈리는 경기가 많습니다. 무실점 비율이 높은 쪽이 유리한 경기입니다.</p>$d$),
('rome-derby', '로마 더비', 'Derby della Capitale', 'SA', 100, 110, 110, $d$<p>AS 로마와 라치오가 같은 경기장 스타디오 올림피코를 나눠 쓰며 치르는 수도 더비입니다. 1900년에 창단한 라치오와 1927년 여러 구단이 합쳐 생긴 로마는 도시의 정체성을 두고 오랫동안 경쟁해 왔습니다.</p><p>경기 전 양쪽 관중석을 가득 채우는 대형 응원 걸개(코레오그라피)로 유명하며, 로마 팬들에게는 시즌 순위보다 더비 결과가 더 중요하다는 말이 나올 정도입니다.</p><p>토리코리 관전 포인트: 로마 더비는 경고와 퇴장이 많은 거친 경기가 되는 경우가 많습니다. 두 팀의 최근 흐름과 함께 주전 선수의 경고 누적 여부를 확인해 보세요.</p>$d$),
('turin-derby', '토리노 더비', 'Derby della Mole', 'SA', 109, 586, 120, $d$<p>유벤투스와 토리노 FC가 이탈리아 북부 도시 토리노에서 치르는 라이벌전입니다. 도시의 상징인 탑 "몰레 안토넬리아나"의 이름을 따서 "데르비 델라 몰레"라고 부르며, 1907년 처음 열린 이탈리아에서 가장 오래된 더비 가운데 하나입니다.</p><p>1940년대에는 "그란데 토리노"가 이탈리아 최강팀이었지만, 1949년 수페르가 비행기 사고 이후 판도가 유벤투스 쪽으로 기울었습니다. 그럼에도 토리노 팬들에게 이 경기는 도시의 진짜 주인을 가리는 자존심 대결입니다.</p><p>토리코리 관전 포인트: 전력 차이가 큰 시즌이 많지만, 토리노는 홈 더비에서 유난히 강한 모습을 보이곤 합니다. 토리노의 홈 경기당 승점을 함께 보면 이변 가능성을 가늠할 수 있습니다.</p>$d$),
('le-classique', '르 클라시크', 'Le Classique', 'FL1', 524, 516, 130, $d$<p>파리 생제르맹과 올랭피크 드 마르세유의 경기는 프랑스 최대의 라이벌전입니다. 수도 파리와 남부 항구 도시 마르세유라는 두 도시의 자존심이 걸려 있으며, 1990년대 두 구단이 리그 우승을 다투면서 라이벌 관계가 본격적으로 굳어졌습니다.</p><p>마르세유는 1993년 프랑스 구단 최초로 챔피언스리그를 우승한 자부심이 있고, 파리 생제르맹은 2011년 카타르 자본에 인수된 뒤 리그를 지배하며 2025년 마침내 챔피언스리그 정상에 올랐습니다.</p><p>토리코리 관전 포인트: 최근에는 파리 생제르맹이 전력에서 앞서는 경우가 많지만, 마르세유의 벨로드롬에서 열리는 경기는 분위기가 완전히 다릅니다. 경기장이 어디인지부터 확인하세요.</p>$d$),
('tyne-wear-derby', '타인-위어 더비', 'Tyne-Wear Derby', 'PL', 67, 71, 140, $d$<p>뉴캐슬 유나이티드와 선덜랜드가 잉글랜드 북동부에서 치르는 라이벌전입니다. 타인강의 뉴캐슬과 위어강의 선덜랜드는 20km 남짓 떨어진 이웃 도시로, 축구 이전부터 산업과 지역 자존심을 두고 경쟁해 왔습니다.</p><p>선덜랜드가 2010년대 후반 하부리그로 떨어지면서 이 더비는 오랫동안 열리지 못했습니다. 선덜랜드가 2025년 프리미어리그로 돌아오면서 두 팀 팬들이 손꼽아 기다리던 경기가 다시 시작됐습니다.</p><p>토리코리 관전 포인트: 오랜만에 재개된 더비는 전력 차이와 상관없이 홈 팀의 응원이 경기 흐름을 좌우하는 경우가 많습니다. 두 팀의 홈 경기당 승점을 비교해 보세요.</p>$d$),
('nordderby', '북부 더비', 'Nordderby', 'BL1', 12, 7, 150, $d$<p>베르더 브레멘과 함부르크 SV가 독일 북부의 패권을 두고 치르는 라이벌전입니다. 두 도시는 모두 항구 도시로, 분데스리가 초창기부터 수없이 맞붙어 왔습니다.</p><p>2009년에는 두 팀이 불과 3주 사이에 리그, DFB 포칼 4강, UEFA컵 4강에서 네 번이나 맞붙는 진기록을 남겼습니다. 함부르크가 2018년 강등된 뒤 한동안 열리지 못했던 이 더비는, 함부르크가 1부로 돌아오면서 다시 분데스리가 일정에 올랐습니다.</p><p>토리코리 관전 포인트: 두 팀 모두 공격적인 경기를 하는 경우가 많아 골이 활발하게 나는 편입니다. 양팀 득점 비율을 함께 확인해 보세요.</p>$d$),
('basque-derby', '바스크 더비', 'Basque Derby', 'PD', 77, 92, 160, $d$<p>아틀레틱 클루브와 레알 소시에다드가 스페인 북부 바스크 지방의 자존심을 두고 치르는 경기입니다. 두 구단 모두 바스크 출신 선수를 중심으로 팀을 꾸리는 전통을 갖고 있어, 지역 정체성이 경기에 그대로 담깁니다.</p><p>두 팀은 2020년 코파 델 레이 결승에서 처음으로 결승 맞대결을 펼쳤습니다. 코로나19로 1년 가까이 미뤄져 2021년 4월 무관중으로 열린 이 결승에서 레알 소시에다드가 1-0으로 이겼습니다.</p><p>토리코리 관전 포인트: 바스크 더비는 다른 더비보다 경기장 분위기가 우호적인 편이지만, 경기 자체는 치열합니다. 두 팀 모두 홈 성적이 좋은 편이라 홈 경기 여부가 중요합니다.</p>$d$),
('seville-derby', '세비야 더비', 'El Gran Derbi', 'PD', 559, 90, 170, $d$<p>세비야 FC와 레알 베티스가 스페인 남부 안달루시아의 세비야에서 치르는 라이벌전으로, "엘 그란 데르비"라고 불립니다. 두 구단 모두 열정적인 팬으로 유명해, 경기가 열리는 날이면 도시 전체가 두 색으로 갈라집니다.</p><p>세비야는 유로파리그 최다 우승팀으로 유럽 무대에서 더 많은 성공을 거뒀고, 베티스는 서민적인 정체성과 뜨거운 응원으로 사랑받아 왔습니다. 그래서 더비 결과가 한 해 분위기를 좌우한다는 말이 나옵니다.</p><p>토리코리 관전 포인트: 세비야 더비는 경고가 많고 흐름이 자주 끊기는 경기가 되기 쉽습니다. 두 팀의 최근 5경기와 홈·원정 성적을 함께 보세요.</p>$d$),
('de-klassieker', '데 클라시커르', 'De Klassieker', 'DED', 678, 675, 180, $d$<p>아약스와 페예노르트의 경기는 네덜란드 최대의 라이벌전입니다. 수도 암스테르담과 항구 도시 로테르담의 경쟁 의식이 그대로 담겨 있으며, 두 구단 모두 유럽 정상에 오른 경험이 있는 명문입니다.</p><p>팬들 사이의 충돌이 잦아, 오랫동안 원정 팬의 경기장 입장을 제한하는 조치가 이어져 왔을 만큼 분위기가 뜨거운 경기입니다.</p><p>토리코리 관전 포인트: 두 팀 모두 공격적인 축구로 유명해 골이 많이 나는 경우가 많습니다. 원정 팬 입장이 제한되는 경우가 많은 만큼 홈 이점이 크게 작용합니다.</p>$d$),
('o-classico', '오 클라시코', 'O Clássico', 'PPL', 1903, 503, 190, $d$<p>벤피카와 FC 포르투의 경기는 포르투갈 최대의 라이벌전입니다. 수도 리스본과 북부 도시 포르투의 지역 경쟁이 담겨 있으며, 두 구단은 스포르팅과 함께 포르투갈 리그 우승을 거의 독차지해 온 "빅3"의 중심입니다.</p><p>두 팀 모두 유럽대항전 우승 경험이 있고, 남미와 아프리카의 유망주를 키워 빅리그로 보내는 역할도 함께 해 왔습니다. 이 경기는 유럽 스카우트들이 가장 많이 지켜보는 경기 가운데 하나이기도 합니다.</p><p>토리코리 관전 포인트: 우승 경쟁에서 직접 승점 6점이 오가는 경기라 두 팀 모두 신중하게 경기를 운영하는 경우가 많습니다. 무승부 가능성도 함께 염두에 두세요.</p>$d$),
('fla-flu', '플라-플루', 'Fla-Flu', 'BSA', 1783, 1765, 200, $d$<p>플라멩구와 플루미넨시가 브라질 리우데자네이루에서 치르는 라이벌전입니다. 1911년 플루미넨시를 떠난 선수들이 플라멩구에 축구부를 만들면서 시작된 인연이라, 두 구단의 역사는 처음부터 얽혀 있습니다.</p><p>1963년 마라카낭 경기장에서 열린 플라-플루에는 20만 명 가까운 관중이 들어차 클럽 경기 역사상 최다 관중 기록으로 남아 있습니다. 브라질 축구 문화를 이해하려면 꼭 봐야 할 경기로 꼽힙니다.</p><p>토리코리 관전 포인트: 브라질 리그는 시즌이 1월에 시작해 12월에 끝나므로, 유럽 비시즌에도 볼 수 있는 빅매치입니다. 두 팀의 최근 5경기 흐름을 함께 확인해 보세요.</p>$d$)
